import {readdir,stat} from 'node:fs';
export function inspect(path,done){
  readdir(path,{withFileTypes:true},function(error,entries){
    if(error)return done(error);
    const names=entries.filter(x=>x.isFile()).map(x=>x.name).sort(),rows=[];
    let index=0;
    function next(){
      if(index===names.length)return done(null,rows);
      const name=names[index++];
      stat(path+'/'+name,function(error,s){if(error)return done(error);rows.push({name,size:s.size,file:s.isFile()});next();});
    }next();
  });
}

