const fs=require('node:fs');const {promisify}=require('node:util');
module.exports=async function(){
  const fd=await promisify(fs.open)('vector.txt','w+');
  try{
    const input=[Buffer.from('ABC'),Buffer.from('\n')];
    const output=[Buffer.alloc(2),Buffer.alloc(4,95)];
    const written=await promisify(fs.writev)(fd,input,0);
    const read=await promisify(fs.readv)(fd,output,0);
    return {written:written.bytesWritten,read:read.bytesRead,writeIdentity:written.buffer===input,
      readIdentity:read.buffers===output,text:Buffer.concat(output).toString()};
  }finally{await promisify(fs.close)(fd);}
};

