module.exports=function(done){
  fs.cp('src','stage',{recursive:true,async filter(source){
    await Promise.resolve();return !source.endsWith('private');
  }},function(error){
    if(error)return done(error);
    fs.copyFile('stage/entry.txt','published.txt',function(error){
      if(error)return done(error);
      fs.rename('stage','dist',function(error){
        if(error)return done(error);
