const fs=require('fs');
module.exports=function(done){
  fs.open('input.txt','r',function(error,fd){
    if(error)return done(error,0,false);
    fs.close(fd,function(error){
      if(error)return done(error,0,false);
      const buffer=Buffer.alloc(4);
      fs.read(fd,buffer,0,4,0,function(error,n,original){
        if(!error)fs.writeFileSync('unexpected.txt',buffer);
        done(error,n,original===buffer);
      });
    });
  });
};
